import type { Metadata } from "next";
import { notFound } from "next/navigation";
import getSupplierDetails from "@/services/getSupplierDetail";
import { getCookie } from "cookies-next";
import getData from "@/services/filterPageService";
import Page from "@/components/tour-category-page/page";

export const dynamicParams = true;
export const dynamic = "force-static";

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  try {
    var data = await getSupplierDetails(params.slug);
    if (!data) throw new Error();
  } catch (error) {
    return {};
  }

  return {
    title: "All Tours By " + data.name + " 2025/2026 - TravelShop Booking",
    description: "",
    alternates: {
      canonical: "/suppliers/" + params.slug,
    },
  };
}

export default async function SupplierDetailPage({
  params,
}: {
  params: { slug: string };
}) {
  try {
    var data = await getSupplierDetails(params.slug);
    if (!data) throw new Error();

    var pageParams = {
      title: "All Tours Operated By " + data.name,
      pageUrl: data.slug,
      breadcrumbTitle: data.name,
      shortDescription: "",
      longDescription: data.description,
      destination: "",
      company: data.slug,
      category: "",
      pageType: "",
      image: "",
      parentCategories: [],
      categories: [],
      pages: [],
      cities: [],
      childPages: [],
      childCategories: [],
    };

    var fetchData = await getData({
      page: 1,
      filterData: { company: data.slug },
      currency: getCookie("currency"),
    });

    return (
      <Page params={pageParams} tourData={{ ...fetchData, filters: [] }} />
    );
  } catch (error) {
    return notFound();
  }
}
