import { apiv3Get } from "@/lib/apiv3";

/**
 * Supplier (operatör) detayı — apiv3 suppliers/{slug}.
 * apiv3 yanıtı { data: {...} }; çağıran düz nesne beklediği için unwrap edilir.
 */
export default async function getSupplierDetails(slug: any) {
  const res = await apiv3Get(`/suppliers/${slug}`, { cache: "force-cache" });

  if (!res.ok) throw new Error("Failed to fetch data");

  const json = await res.json();
  return json.data ?? null;
}
